        sum(Pvals[Int((d.i - Int32(1)) * Int32(87) + k)] * x[Pcols[Int((d.i - Int32(1)) * Int32(87) + k)]] for k in 1:87) - Prhs[Int(d.i)]
        for d in con_data_18; lcon = T(-5.0), ucon = T(0.0))
    return ExaModels.ExaModel(c; kwargs...)
end
